head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > P > hideHeader]<br/>GridView 컴포넌트의 Header 영역을 숨길지 설정합니다.",
    "validation" : [
        "미설정 또는 false 설정 시 GridView 의 Header 영역을 표시합니다. (기본값 false)",
        "true 설정 시 GridView 의 Header 영역을 숨김 처리하여 표시하지 않습니다.",
        "Header 영역은 'display:none' 으로 숨김 처리되므로, 숨긴 상태에서도 메소드를 사용한 Header Column 접근이 가능합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 조건 설정
    //  - con_hideHeader 가 미설정('') 이면 properties 에 hideHeader 키를 전달하지 않음
    //    (createCList 가 빈 문자열 value 를 자동 제외하므로 키 자체가 빠짐)
    let properties = {
        hideHeader: con_hideHeader.getValue(),
        dataList: "data:dlt_bind",
    };

    let cList = $c.gcm.createCList(properties);

    // dataList 생성
    $c.gcm.createDynamicDataList('', '', 'dlt_bind');

    // target 생성
    $c.gcm.createBasicGridView(cList);

    scwin.btn_hideHeader_onclick();
}



scwin.btn_hideHeader_onclick = function (e) {
    // Header 영역(head_table)의 표시 상태 확인
    let headTable = document.querySelector("[id*='target1_head_table']");

    if (headTable) {
        let displayValue = window.getComputedStyle(headTable).display;
        let isHidden = (displayValue === "none");

        wf_body_bottom.getObj("scwin").setReturnValue("Header 영역 display : " + displayValue);
        wf_body_bottom.getObj("scwin").setReturnValue("Header 영역 숨김 여부 : " + isHidden);
    }
}



scwin.btn_getHeaderID_onclick = function (e) {
    // @spec 검증 : Header 영역이 display:none 으로 숨겨진 상태에서도
    //              메소드를 사용한 Header Column 접근이 가능한지 확인
    let rtn = target1.getHeaderID(0);
    wf_body_bottom.getObj("scwin").setReturnValue("getHeaderID(0) : " + rtn);
};
